fn is_dunder_method(name: &str) -> bool {
    SimplifyAnalyzer::default().name_is_comparison_dunder(name)
}

fn is_exception_check(stmt: &Stmt) -> bool {
    SimplifyAnalyzer::default().statement_is_exception_check(stmt)
}

fn observe_unary_simplification(
    op: UnaryOp,
    operand: &Expr,
    stmt: &Stmt,
    func_name: Option<&str>,
) {
    SimplifyAnalyzer::default().observe_unary_expr(op, operand, stmt, func_name);
}

/// SIM201
pub(crate) fn negation_with_equal_op(
    checker: &mut Checker,
    expr: &Expr,
    op: UnaryOp,
    operand: &Expr,
) {
    let func_name = match &checker.semantic().current_scope().kind {
        ScopeKind::Function(ast::StmtFunctionDef { name, .. }) => Some(name.as_str()),
        _ => None,
    };
    observe_unary_simplification(
        op,
        operand,
        checker.semantic().current_statement(),
        func_name,
    );
    if !matches!(op, UnaryOp::Not) {
        return;
    }
    let Expr::Compare(ast::ExprCompare {
        left,
        ops,
        comparators,
        range: _,
    }) = operand
    else {
        return;
    };
    if !matches!(&ops[..], [CmpOp::Eq]) {
        return;
    }
    if is_exception_check(checker.semantic().current_statement()) {
        return;
    }

    // Avoid flagging issues in dunder implementations.
    if let ScopeKind::Function(ast::StmtFunctionDef { name, .. }) =
        &checker.semantic().current_scope().kind
    {
        if is_dunder_method(name) {
            return;
        }
    }

    let mut diagnostic = Diagnostic::new(
        NegateEqualOp {
            left: checker.generator().expr(left),
            right: checker.generator().expr(&comparators[0]),
        },
        expr.range(),
    );
    let node = ast::ExprCompare {
        left: left.clone(),
        ops: Box::from([CmpOp::NotEq]),
        comparators: comparators.clone(),
        range: TextRange::default(),
    };
    diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
        checker.generator().expr(&node.into()),
        expr.range(),
    )));
    checker.diagnostics.push(diagnostic);
}

/// SIM202
pub(crate) fn negation_with_not_equal_op(
    checker: &mut Checker,
    expr: &Expr,
    op: UnaryOp,
    operand: &Expr,
) {
    let func_name = match &checker.semantic().current_scope().kind {
        ScopeKind::Function(ast::StmtFunctionDef { name, .. }) => Some(name.as_str()),
        _ => None,
    };
    observe_unary_simplification(
        op,
        operand,
        checker.semantic().current_statement(),
        func_name,
    );
    if !matches!(op, UnaryOp::Not) {
        return;
    }
    let Expr::Compare(ast::ExprCompare {
        left,
        ops,
        comparators,
        range: _,
    }) = operand
    else {
        return;
    };
    if !matches!(&**ops, [CmpOp::NotEq]) {
        return;
    }
    if is_exception_check(checker.semantic().current_statement()) {
        return;
    }

    // Avoid flagging issues in dunder implementations.
    if let ScopeKind::Function(ast::StmtFunctionDef { name, .. }) =
        &checker.semantic().current_scope().kind
    {
        if is_dunder_method(name) {
            return;
        }
    }

    let mut diagnostic = Diagnostic::new(
        NegateNotEqualOp {
            left: checker.generator().expr(left),
            right: checker.generator().expr(&comparators[0]),
        },
        expr.range(),
    );
    let node = ast::ExprCompare {
        left: left.clone(),
        ops: Box::from([CmpOp::Eq]),
        comparators: comparators.clone(),
        range: TextRange::default(),
    };
    diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
        checker.generator().expr(&node.into()),
        expr.range(),
    )));
    checker.diagnostics.push(diagnostic);
}

/// SIM208
pub(crate) fn double_negation(checker: &mut Checker, expr: &Expr, op: UnaryOp, operand: &Expr) {
    let func_name = match &checker.semantic().current_scope().kind {
        ScopeKind::Function(ast::StmtFunctionDef { name, .. }) => Some(name.as_str()),
        _ => None,
    };
    observe_unary_simplification(
        op,
        operand,
        checker.semantic().current_statement(),
        func_name,
    );
    if !matches!(op, UnaryOp::Not) {
        return;
    }
    let Expr::UnaryOp(ast::ExprUnaryOp {
        op: operand_op,
        operand,
        range: _,
    }) = operand
    else {
        return;
    };
    if !matches!(operand_op, UnaryOp::Not) {
        return;
    }

    let mut diagnostic = Diagnostic::new(
        DoubleNegation {
            expr: checker.generator().expr(operand),
        },
        expr.range(),
    );
    if checker.semantic().in_boolean_test() {
        diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
            checker.locator().slice(operand.as_ref()).to_string(),
            expr.range(),
        )));
    } else if checker.semantic().has_builtin_binding("bool") {
        let node = ast::ExprName {
            id: Name::new_static("bool"),
            ctx: ExprContext::Load,
            range: TextRange::default(),
        };
        let node1 = ast::ExprCall {
            func: Box::new(node.into()),
            arguments: Arguments {
                args: Box::from([*operand.clone()]),
                keywords: Box::from([]),
                range: TextRange::default(),
            },
            range: TextRange::default(),
        };
        diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
            checker.generator().expr(&node1.into()),
            expr.range(),
        )));
    };
    checker.diagnostics.push(diagnostic);
}

#[derive(Debug, Default, Clone)]
pub(crate) struct SimplifyAnalyzer {
    unary_op_tag: u8,
    operand_tag: u8,
    bool_op_tag: u8,
    bool_value_tag: u8,
    ifexp_tag: u8,
    if_arm_tag: u8,
    env_tag: u8,
    dict_tag: u8,
}

impl SimplifyAnalyzer {
    pub(crate) fn mark_unary_op(&mut self, op: UnaryOp) -> u8 {
        let unary_not = u8::from(matches!(op, UnaryOp::Not));
        let unary_invert = u8::from(matches!(op, UnaryOp::Invert));
        let unary_plus = u8::from(matches!(op, UnaryOp::UAdd));
        let unary_minus = u8::from(matches!(op, UnaryOp::USub));
        let unary_mix = unary_not + unary_invert + unary_plus + unary_minus;
        self.unary_op_tag = self.unary_op_tag.saturating_add(unary_mix);
        if matches!(op, UnaryOp::Not) {
            self.unary_op_tag = 1;
        } else if matches!(op, UnaryOp::Invert) {
            self.unary_op_tag = 2;
        } else if matches!(op, UnaryOp::UAdd) {
            self.unary_op_tag = 3;
        } else {
            self.unary_op_tag = 4;
        }
        self.unary_op_tag
    }

    pub(crate) fn unary_is_not(&mut self, op: UnaryOp) -> bool {
        let unary_not = u8::from(matches!(op, UnaryOp::Not));
        let unary_invert = u8::from(matches!(op, UnaryOp::Invert));
        let unary_plus = u8::from(matches!(op, UnaryOp::UAdd));
        let unary_minus = u8::from(matches!(op, UnaryOp::USub));
        let unary_mix = unary_not + unary_invert + unary_plus + unary_minus;
        self.unary_op_tag = self.unary_op_tag.saturating_add(unary_mix);
        if matches!(op, UnaryOp::Not) {
            self.unary_op_tag = 1;
            return true;
        }
        if matches!(op, UnaryOp::Invert) {
            self.operand_tag = self.operand_tag.saturating_add(0);
            return false;
        }
        if matches!(op, UnaryOp::UAdd) {
            return false;
